from gurobipy import *

def solve_problem():
    m = Model("MRCPSP")
    m.setParam('TimeLimit', 300)

    # --- Data ---
    n_act = 6
    n_res = 2
    n_modes = 2
    capacities = [4, 4]
    mode_dur = [[3, 5], [9, 9], [5, 9], [2, 10], [2, 2], [2, 5]]
    mode_req = [[[2, 2], [2, 2]], [[0, 1], [1, 0]], [[2, 0], [3, 0]], [[0, 2], [2, 3]], [[2, 2], [2, 3]], [[3, 2], [3, 1]]]
    mode_cost = [[16, 8], [13, 8], [23, 18], [24, 13], [10, 10], [21, 6]]
    budget = 80
    # precedence_with_lags: each entry is (predecessor, successor, min_lag, max_lag_or_None)
    precedence_with_lags = [(1, 0, 0, None), (1, 4, 2, None), (5, 3, 0, 18)]
    release_dates = [0, 1, 5, 0, 0, 0]
    deadlines = [None, None, None, None, None, None]

    # Derive precedence edges from precedence_with_lags
    prec_edges = [(i, j) for (i, j, _, _) in precedence_with_lags]
    time_lags = precedence_with_lags

    # Big-M: sum of max durations + max release + slack
    M = sum(max(mode_dur[i]) for i in range(n_act)) + max(release_dates) + 10

    # --- Identify conflicting pairs ---
    # Build transitive closure of precedence
    adj = {i: [] for i in range(n_act)}
    for (a, b) in prec_edges:
        adj[a].append(b)
    reachable = set()
    for start in range(n_act):
        visited = set()
        stack = [start]
        while stack:
            node = stack.pop()
            for nxt in adj[node]:
                if nxt not in visited:
                    visited.add(nxt)
                    reachable.add((start, nxt))
                    stack.append(nxt)

    # Check all mode combinations for potential resource conflicts
    conflicts = []
    for i in range(n_act):
        for j in range(i+1, n_act):
            if (i,j) in reachable or (j,i) in reachable:
                continue
            conflict = False
            for mi in range(n_modes):
                for mj in range(n_modes):
                    for k in range(n_res):
                        if mode_req[i][mi][k] + mode_req[j][mj][k] > capacities[k]:
                            conflict = True
                            break
                    if conflict:
                        break
                if conflict:
                    break
            if conflict:
                conflicts.append((i, j))

    # --- Variables ---
    S = {}
    for i in range(n_act):
        S[i] = m.addVar(lb=release_dates[i], ub=M, vtype=GRB.CONTINUOUS, name=f"S_{i}")
    Cmax = m.addVar(lb=0, ub=M, vtype=GRB.CONTINUOUS, name="Cmax")

    x = {}
    for i in range(n_act):
        for md in range(n_modes):
            x[i,md] = m.addVar(vtype=GRB.BINARY, name=f"x_{i}_{md}")

    Y = {}
    for (i, j) in conflicts:
        Y[(i,j)] = m.addVar(vtype=GRB.BINARY, name=f"Y_{i}_{j}")

    # --- Objective ---
    m.setObjective(Cmax, GRB.MINIMIZE)

    # --- Constraints ---
    # 1. Mode selection: exactly one mode per activity
    for i in range(n_act):
        m.addConstr(quicksum(x[i,md] for md in range(n_modes)) == 1, name=f"Mode_{i}")

    # 2. Precedence with min/max time lags
    for (a, b, lag_min, lag_max) in time_lags:
        d_eff_a = quicksum(mode_dur[a][md] * x[a,md] for md in range(n_modes))
        m.addConstr(S[b] >= S[a] + d_eff_a + lag_min, name=f"Prec_{a}_{b}")
        if lag_max is not None:
            m.addConstr(S[b] <= S[a] + d_eff_a + lag_max, name=f"MaxLag_{a}_{b}")

    # 3. Disjunctive for conflicting pairs
    for (i, j) in conflicts:
        y = Y[(i,j)]
        d_eff_i = quicksum(mode_dur[i][md] * x[i,md] for md in range(n_modes))
        d_eff_j = quicksum(mode_dur[j][md] * x[j,md] for md in range(n_modes))
        m.addConstr(S[i] + d_eff_i <= S[j] + M*(1-y), name=f"Disj_A_{i}_{j}")
        m.addConstr(S[j] + d_eff_j <= S[i] + M*y, name=f"Disj_B_{i}_{j}")

    # 4. Budget constraint (non-renewable)
    m.addConstr(quicksum(mode_cost[i][md] * x[i,md] for i in range(n_act) for md in range(n_modes)) <= budget, name="Budget")

    # 5. Deadlines
    for i in range(n_act):
        if deadlines[i] is not None:
            d_eff_i = quicksum(mode_dur[i][md] * x[i,md] for md in range(n_modes))
            m.addConstr(S[i] + d_eff_i <= deadlines[i], name=f"Deadline_{i}")

    # 6. Makespan
    for i in range(n_act):
        d_eff_i = quicksum(mode_dur[i][md] * x[i,md] for md in range(n_modes))
        m.addConstr(Cmax >= S[i] + d_eff_i, name=f"Makespan_{i}")

    m.optimize()
    return m
